// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

library Actions {
    /// @dev toChain, recipient, amount, txid are validated
    struct DepositBtcActionV0 {
        uint256 toChain;
        address recipient;
        uint256 amount;
        bytes32 txid;
        uint32 vout;
    }

    /// @dev toChain, recipient, amount, txid, token are validated
    struct DepositBtcActionV1 {
        uint256 toChain;
        address recipient;
        uint256 amount;
        bytes32 txid;
        uint32 vout;
        address token;
    }

    struct DepositBridgeAction {
        uint256 fromChain;
        bytes32 fromContract;
        uint256 toChain;
        address toContract;
        address recipient;
        uint64 amount;
        uint256 nonce;
    }

    struct ValSetAction {
        uint256 epoch;
        address[] validators;
        uint256[] weights;
        uint256 weightThreshold;
        uint256 height;
    }

    struct FeeApprovalAction {
        uint256 fee;
        uint256 expiry;
    }

    struct RatioUpdate {
        bytes32 denom;
        uint256 ratio;
        uint256 switchTime;
    }

    /// @dev Error thrown when invalid public key is provided
    error InvalidPublicKey(bytes pubKey);

    /// @dev Error thrown when signatures length is not equal to signers length
    error Actions_LengthMismatch();

    /// @dev Error thrown when threshold is invalid
    error InvalidThreshold();

    /// @dev Error thrown when validator set size is invalid
    error InvalidValidatorSetSize();

    /// @dev Error thrown when zero validator is provided
    error ZeroValidator();

    /// @dev Error thrown when wrong chain id is provided
    error WrongChainId();

    /// @dev Error thrown when wrong contract is provided
    error WrongContract();

    /// @dev Error thrown when zero address is provided
    error Actions_ZeroAddress();

    /// @dev Error thrown when zero amount is provided
    error ZeroAmount();

    /// @dev Error thrown when zero weight is provided
    error ZeroWeight();

    /// @dev Error thrown when fee approval is expired
    error UserSignatureExpired(uint256 expiry);

    /// @dev Error thrown when amount is below fee
    error NotEnoughAmountToUseApproval();

    /// @dev Error thrown when zero fee is used
    error ZeroFee();

    /// @dev Error thrown when payload length is too big
    error InvalidPayloadSize(uint256 expected, uint256 actual);

    error ZeroTxId();

    error InvalidDestinationToken(address expected, address actual);

    error Actions_ZeroDenom();

    error Actions_ZeroRatio();

    // bytes4(keccak256("feeApproval(uint256,uint256)"))
    bytes4 internal constant FEE_APPROVAL_ACTION = 0x8175ca94;
    // keccak256("feeApproval(uint256 chainId,uint256 fee,uint256 expiry)")
    bytes32 internal constant FEE_APPROVAL_EIP712_ACTION =
        0x40ac9f6aa27075e64c1ed1ea2e831b20b8c25efdeb6b79fd0cf683c9a9c50725;
    // bytes4(keccak256("payload(bytes32,bytes32,uint64,bytes32,uint32)"))
    bytes4 internal constant DEPOSIT_BTC_ACTION_V0 = 0xf2e73f7c;
    // bytes4(keccak256("payload(bytes32,bytes32,uint64,bytes32,uint32,bytes32)"))
    bytes4 internal constant DEPOSIT_BTC_ACTION_V1 = 0xce25e7c2;
    // bytes4(keccak256("payload(bytes32,bytes32,bytes32,bytes32,bytes32,uint64,uint256)"))
    bytes4 internal constant DEPOSIT_BRIDGE_ACTION = 0x5c70a505;
    // bytes4(keccak256("payload(uint256,bytes[],uint256[],uint256,uint256)"))
    bytes4 internal constant NEW_VALSET = 0x4aab1d6f;
    // bytes4(keccak256("payload(bytes32,uint256,uint256)"))
    bytes4 internal constant RATIO_UPDATE = 0x6c722c2c;

    /// @dev Maximum number of validators allowed in the consortium.
    /// @notice This value is determined by the minimum of CometBFT consensus limitations and gas considerations:
    /// - CometBFT has a hard limit of 10,000 validators (https://docs.cometbft.com/v0.38/spec/core/state)
    /// - Gas-based calculation:
    ///   - Assumes 4281 gas per ECDSA signature verification
    ///   - Uses a conservative 30 million gas block limit
    ///   - Maximum possible signatures: 30,000,000 / 4,281 ≈ 7007
    ///   - Reverse calculated for BFT consensus (2/3 + 1):
    ///     7,007 = (10,509 * 2/3 + 1) rounded down
    /// - The lower value of 10,000 (CometBFT limit) and 10,509 (gas calculation) is chosen
    /// @dev This limit ensures compatibility with CometBFT while also considering gas limitations
    ///      for signature verification within a single block.
    uint256 private constant MAX_VALIDATOR_SET_SIZE = 102;

    /// @dev Minimum number of validators allowed in the system.
    /// @notice While set to 1 to allow for non-distributed scenarios, this configuration
    /// does not provide Byzantine fault tolerance. For a truly distributed and
    /// fault-tolerant system, a minimum of 4 validators would be recommended to tolerate
    /// at least one Byzantine fault.
    uint256 private constant MIN_VALIDATOR_SET_SIZE = 1;

    /// @dev A constant representing the number of bytes for a slot of information in a payload.
    uint256 internal constant ABI_SLOT_SIZE = 32;

    /**
     * @notice Returns decoded deposit btc msg v0
     * @dev Message should not contain the selector
     * @param payload Body of the mint payload
     */
    function depositBtcV0(
        bytes memory payload
    ) internal view returns (DepositBtcActionV0 memory) {
        if (payload.length != ABI_SLOT_SIZE * 5)
            revert InvalidPayloadSize(ABI_SLOT_SIZE * 5, payload.length);

        (
            uint256 toChain,
            address recipient,
            uint256 amount,
            bytes32 txid,
            uint32 vout
        ) = abi.decode(payload, (uint256, address, uint256, bytes32, uint32));

        if (toChain != block.chainid) {
            revert WrongChainId();
        }
        if (recipient == address(0)) {
            revert Actions_ZeroAddress();
        }
        if (amount == 0) {
            revert ZeroAmount();
        }
        if (txid == bytes32(0)) {
            revert ZeroTxId();
        }

        return DepositBtcActionV0(toChain, recipient, amount, txid, vout);
    }

    /**
     * @notice Returns decoded deposit btc msg v1
     * @dev Message should not contain the selector
     * @param payload Body of the mint payload
     */
    function depositBtcV1(
        bytes memory payload
    ) internal view returns (DepositBtcActionV1 memory) {
        if (payload.length != ABI_SLOT_SIZE * 6)
            revert InvalidPayloadSize(ABI_SLOT_SIZE * 6, payload.length);

        (
            uint256 toChain,
            address recipient,
            uint256 amount,
            bytes32 txid,
            uint32 vout,
            address token
        ) = abi.decode(
                payload,
                (uint256, address, uint256, bytes32, uint32, address)
            );

        if (toChain != block.chainid) {
            revert WrongChainId();
        }
        if (recipient == address(0)) {
            revert Actions_ZeroAddress();
        }
        if (amount == 0) {
            revert ZeroAmount();
        }
        if (txid == bytes32(0)) {
            revert ZeroTxId();
        }
        if (token != address(this)) {
            revert InvalidDestinationToken(address(this), token);
        }

        return
            DepositBtcActionV1(toChain, recipient, amount, txid, vout, token);
    }

    /**
     * @notice Returns decoded bridge payload
     * @dev Payload should not contain the selector
     * @param payload Body of the burn payload
     */
    function depositBridge(
        bytes memory payload
    ) internal view returns (DepositBridgeAction memory) {
        if (payload.length != ABI_SLOT_SIZE * 7)
            revert InvalidPayloadSize(ABI_SLOT_SIZE * 7, payload.length);

        (
            uint256 fromChain,
            bytes32 fromContract,
            uint256 toChain,
            address toContract,
            address recipient,
            uint64 amount,
            uint256 nonce
        ) = abi.decode(
                payload,
                (uint256, bytes32, uint256, address, address, uint64, uint256)
            );

        if (toChain != block.chainid) {
            revert WrongChainId();
        }
        if (recipient == address(0)) {
            revert Actions_ZeroAddress();
        }
        if (amount == 0) {
            revert ZeroAmount();
        }

        return
            DepositBridgeAction(
                fromChain,
                fromContract,
                toChain,
                toContract,
                recipient,
                amount,
                nonce
            );
    }

    /**
     * @notice Returns decoded validator set
     * @dev Payload should not contain the selector
     * @param payload Body of the set validators set payload
     */
    function validateValSet(
        bytes memory payload
    ) internal pure returns (ValSetAction memory) {
        (
            uint256 epoch,
            bytes[] memory pubKeys,
            uint256[] memory weights,
            uint256 weightThreshold,
            uint256 height
        ) = abi.decode(
                payload,
                (uint256, bytes[], uint256[], uint256, uint256)
            );

        // Since dynamic arrays can variably insert more slots of data for things such as data length,
        // offset etc., we will just encode the received variables again and check for a length match.
        bytes memory reEncodedPayload = abi.encode(
            epoch,
            pubKeys,
            weights,
            weightThreshold,
            height
        );
        if (reEncodedPayload.length != payload.length)
            revert InvalidPayloadSize(payload.length, reEncodedPayload.length);

        if (
            pubKeys.length < MIN_VALIDATOR_SET_SIZE ||
            pubKeys.length > MAX_VALIDATOR_SET_SIZE
        ) revert InvalidValidatorSetSize();

        if (pubKeys.length != weights.length) revert Actions_LengthMismatch();

        if (weightThreshold == 0) revert InvalidThreshold();

        uint256 sum = 0;
        for (uint256 i; i < weights.length; ) {
            if (weights[i] == 0) {
                revert ZeroWeight();
            }
            sum += weights[i];
            unchecked {
                ++i;
            }
        }
        if (sum < weightThreshold) revert InvalidThreshold();

        address[] memory validators = pubKeysToAddress(pubKeys);

        return
            ValSetAction(epoch, validators, weights, weightThreshold, height);
    }

    function pubKeysToAddress(
        bytes[] memory _pubKeys
    ) internal pure returns (address[] memory) {
        address[] memory addresses = new address[](_pubKeys.length);
        for (uint256 i; i < _pubKeys.length; ) {
            // each pubkey represented as uncompressed

            if (_pubKeys[i].length == 65) {
                bytes memory data = _pubKeys[i];

                // Ensure that first byte of pubkey is 0x04
                if (_pubKeys[i][0] != 0x04)
                    revert InvalidPublicKey(_pubKeys[i]);

                // create a new array with length - 1 (excluding the first 0x04 byte)
                bytes memory result = new bytes(data.length - 1);

                // use inline assembly for memory manipulation
                assembly {
                    // calculate the start of the `result` and `data` in memory
                    let resultData := add(result, 0x20) // points to the first byte of the result
                    let dataStart := add(data, 0x21) // points to the second byte of data (skip 0x04)

                    // copy 64 bytes from input (excluding the first byte) to result
                    mstore(resultData, mload(dataStart)) // copy the first 32 bytes
                    mstore(add(resultData, 0x20), mload(add(dataStart, 0x20))) // copy the next 32 bytes
                }

                addresses[i] = address(uint160(uint256(keccak256(result))));
            } else {
                revert InvalidPublicKey(_pubKeys[i]);
            }

            unchecked {
                ++i;
            }
        }
        return addresses;
    }

    /**
     * @notice Returns decoded fee approval
     * @dev Payload should not contain the selector
     * @param payload Body of the fee approval payload
     */
    function feeApproval(
        bytes memory payload
    ) internal view returns (FeeApprovalAction memory) {
        if (payload.length != ABI_SLOT_SIZE * 2)
            revert InvalidPayloadSize(ABI_SLOT_SIZE * 2, payload.length);

        (uint256 fee, uint256 expiry) = abi.decode(payload, (uint256, uint256));

        if (block.timestamp > expiry) {
            revert UserSignatureExpired(expiry);
        }
        if (fee == 0) {
            revert ZeroFee();
        }

        return FeeApprovalAction(fee, expiry);
    }

    /**
     * @notice Returns decoded ratio update message
     * @dev Message should not contain the selector
     * @param payload Body of the ratio update message
     */
    function ratioUpdate(
        bytes memory payload
    ) internal pure returns (RatioUpdate memory) {
        if (payload.length != ABI_SLOT_SIZE * 3)
            revert InvalidPayloadSize(ABI_SLOT_SIZE * 3, payload.length);

        (bytes32 denom, uint256 ratio, uint256 timestamp) = abi.decode(
            payload,
            (bytes32, uint256, uint256)
        );

        if (denom == bytes32(0)) {
            revert Actions_ZeroDenom();
        }
        if (ratio == uint256(0)) {
            revert Actions_ZeroRatio();
        }

        return RatioUpdate(denom, ratio, timestamp);
    }
}

contracts/stakeAndBake/StakeAndBakeNativ.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {INativeLBTC} from "../LBTC/interfaces/INativeLBTC.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {IDepositor} from "./depositor/IDepositor.sol";
import {IERC20} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Actions} from "../libs/Actions.sol";

/**
 * @title Convenience contract for users who wish to
 * stake their BTC and deposit it in a vault in the same transaction.
 * @author Lombard.Finance
 * @notice This contract is a part of the Lombard.Finance protocol
 */
contract StakeAndBakeNativeToken is
    AccessControlUpgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable
{
    using SafeERC20 for IERC20;

    /// @dev error thrown when the remaining amount after taking a fee is zero
    error ZeroDepositAmount();
    /// @dev error thrown when operator is changed to zero address
    error ZeroAddress();
    /// @dev error thrown when fee is attempted to be set above hardcoded maximum
    error FeeGreaterThanMaximum(uint256 fee);
    /// @dev error thrown when no depositor is set
    error NoDepositorSet();
    /// @dev error thrown when stakeAndBakeInternal is called by anyone other than self
    error CallerNotSelf(address caller);
    /// @dev error thrown when amount to be staked is more than permit amount
    error WrongAmount();
    /// @dev error thrown when permit payload is wrong
    error InvalidPermitPayload();

    event DepositorSet(address indexed depositor);
    event BatchStakeAndBakeReverted(
        uint256 indexed index,
        string message,
        bytes customError
    );
    event FeeChanged(uint256 newFee);
    event GasLimitChanged(uint256 newGasLimit);

    struct StakeAndBakeData {
        /// @notice Contents of permit approval signed by the user
        bytes permitPayload;
        /// @notice Contains the parameters needed to complete a deposit
        bytes depositPayload;
        /// @notice The message with the stake data
        bytes mintPayload;
        /// @notice Signature of the consortium approving the mint
        bytes proof;
        /// @notice Amount to be staked, should be the same or less than amount minted
        uint256 amount;
    }

    /// @custom:storage-location erc7201:lombardfinance.storage.StakeAndBakeNativeToken
    struct StakeAndBakeNativeTokenStorage {
        IERC20 nativeLbtc;
        INativeLBTC adapter;
        IDepositor depositor;
        /// @notice Amount to be taken as fee in minimal units of token to be staked
        uint256 fee;
        uint256 gasLimit;
    }

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant FEE_OPERATOR_ROLE = keccak256("FEE_OPERATOR_ROLE");
    bytes32 public constant CLAIMER_ROLE = keccak256("CLAIMER_ROLE");

    // keccak256(abi.encode(uint256(keccak256("lombardfinance.storage.StakeAndBakeNativeToken")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant STAKE_AND_BAKE_STORAGE_LOCATION =
        0x0e47f6bdb2c8c295db7a485b9611b576c67616f4bb0fcb676c069d08170f1800;

    /// @notice The maximum possible fee in token minimal units
    uint256 public constant MAXIMUM_FEE = 100000;

    /// @dev https://docs.openzeppelin.com/upgrades-plugins/1.x/writing-upgradeable#initializing_the_implementation_contract
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    modifier depositorSet() {
        if (
            address(_getStakeAndBakeNativeTokenStorage().depositor) ==
            address(0)
        ) {
            revert NoDepositorSet();
        }
        _;
    }

    function initialize(
        IERC20 nativeLbtc_,
        INativeLBTC adapter_,
        address owner_,
        address operator_,
        uint256 fee_,
        address claimer_,
        address pauser_,
        uint256 gasLimit_
    ) external initializer {
        if (fee_ > MAXIMUM_FEE) revert FeeGreaterThanMaximum(fee_);
        if (address(adapter_) == address(0)) {
            revert ZeroAddress();
        }

        __ReentrancyGuard_init();
        __Pausable_init();
        __AccessControl_init();

        _grantRole(DEFAULT_ADMIN_ROLE, owner_);
        _grantRole(FEE_OPERATOR_ROLE, operator_);
        _grantRole(PAUSER_ROLE, pauser_);
        _grantRole(CLAIMER_ROLE, claimer_);

        // We need the stake and bake contract to hold a claimer role as well, for when we call
        // `batchStakeAndBake`.
        _grantRole(CLAIMER_ROLE, address(this));

        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();
        $.nativeLbtc = nativeLbtc_;
        $.adapter = adapter_;
        $.fee = fee_;
        $.gasLimit = gasLimit_;
    }

    /**
     * @notice Sets the claiming fee
     * @param fee The fee to set
     */
    function setFee(uint256 fee) external onlyRole(FEE_OPERATOR_ROLE) {
        if (fee > MAXIMUM_FEE) revert FeeGreaterThanMaximum(fee);
        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();
        $.fee = fee;
        emit FeeChanged(fee);
    }

    /**
     * @notice Sets the maximum gas limit for each stake and bake call
     * @param gasLimit The gas limit to set
     */
    function setGasLimit(
        uint256 gasLimit
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();
        $.gasLimit = gasLimit;
        emit GasLimitChanged(gasLimit);
    }

    /**
     * @notice Sets a depositor, allowing the contract to `stakeAndBake` to it.
     * @param depositor The address of the depositor abstraction we use to deposit to the vault
     */
    function setDepositor(
        address depositor
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (depositor == address(0)) revert ZeroAddress();
        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();
        $.depositor = IDepositor(depositor);
        emit DepositorSet(depositor);
    }

    /**
     * @notice Mint LBTC and stake directly into a given vault in batches.
     */
    function batchStakeAndBake(
        StakeAndBakeData[] calldata data
    )
        external
        nonReentrant
        onlyRole(CLAIMER_ROLE)
        depositorSet
        whenNotPaused
        returns (bytes[] memory)
    {
        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();
        bytes[] memory ret = new bytes[](data.length);
        for (uint256 i; i < data.length; ) {
            try this.stakeAndBakeInternal{gas: $.gasLimit}(data[i]) returns (
                bytes memory b
            ) {
                ret[i] = b;
            } catch Error(string memory message) {
                emit BatchStakeAndBakeReverted(i, message, "");
            } catch (bytes memory lowLevelData) {
                emit BatchStakeAndBakeReverted(i, "", lowLevelData);
            }

            unchecked {
                i++;
            }
        }

        return ret;
    }

    function stakeAndBakeInternal(
        StakeAndBakeData calldata data
    ) external returns (bytes memory) {
        if (_msgSender() != address(this)) {
            revert CallerNotSelf(_msgSender());
        }
        return _stakeAndBake(data);
    }

    /**
     * @notice Mint LBTC and stake directly into a given vault.
     * @param data The bundled data needed to execute this function
     */
    function stakeAndBake(
        StakeAndBakeData calldata data
    )
        external
        nonReentrant
        onlyRole(CLAIMER_ROLE)
        depositorSet
        whenNotPaused
        returns (bytes memory)
    {
        return
            this.stakeAndBakeInternal{
                gas: _getStakeAndBakeNativeTokenStorage().gasLimit
            }(data);
    }

    function getStakeAndBakeFee() external view returns (uint256) {
        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();
        return $.fee;
    }

    function getStakeAndBakeDepositor() external view returns (IDepositor) {
        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();
        return $.depositor;
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    function getTokenAndAdapter() external view returns (IERC20, INativeLBTC) {
        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();
        return ($.nativeLbtc, $.adapter);
    }

    function _deposit(
        uint256 stakeAmount,
        address owner,
        bytes calldata depositPayload
    ) internal returns (bytes memory) {
        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();

        // Since a vault could only work with msg.sender, the depositor needs to own the LBTC.
        // The depositor should then send the staked vault shares back to the `owner`.
        $.nativeLbtc.safeIncreaseAllowance(address($.depositor), stakeAmount);

        // Finally, deposit LBTC to the given vault.
        return $.depositor.deposit(owner, stakeAmount, depositPayload);
    }

    function _stakeAndBake(
        StakeAndBakeData calldata data
    ) internal returns (bytes memory) {
        StakeAndBakeNativeTokenStorage
            storage $ = _getStakeAndBakeNativeTokenStorage();

        // First, mint the LBTC.
        $.adapter.mintV1(data.mintPayload, data.proof);
        // Get the recipient.
        (, address owner, , , , ) = abi.decode(
            data.mintPayload[4:],
            (uint256, address, uint256, bytes32, uint32, address)
        );

        // We check if we can simply use transferFrom.
        // Otherwise, we permit the depositor to transfer the minted value.,
        if ($.nativeLbtc.allowance(owner, address(this)) < data.amount) {
            if (data.permitPayload.length < 83) {
                revert InvalidPermitPayload();
            }
            (
                uint256 permitAmount,
                uint256 deadline,
                uint8 v,
                bytes32 r,
                bytes32 s
            ) = abi.decode(
                    data.permitPayload,
                    (uint256, uint256, uint8, bytes32, bytes32)
                );

            if (data.amount > permitAmount) {
                revert WrongAmount();
            }
            IERC20Permit(address($.nativeLbtc)).permit(
                owner,
                address(this),
                permitAmount,
                deadline,
                v,
                r,
                s
            );
        }

        $.nativeLbtc.safeTransferFrom(owner, address(this), data.amount);

        // Take the current maximum fee from the user.
        uint256 feeAmount = $.fee;
        if (data.amount <= feeAmount) {
            revert ZeroDepositAmount();
        }
        if (feeAmount > 0) {
            $.nativeLbtc.safeTransfer($.adapter.getTreasury(), feeAmount);
        }
        return _deposit(data.amount - feeAmount, owner, data.depositPayload);
    }

    function _getStakeAndBakeNativeTokenStorage()
        private
        pure
        returns (StakeAndBakeNativeTokenStorage storage $)
    {
        assembly {
            $.slot := STAKE_AND_BAKE_STORAGE_LOCATION
        }
    }
}

contracts/stakeAndBake/depositor/IDeposi.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/**
 * @title Interface to abstract over specifics of depositing into a vault.
 * This just makes sure that any vault contract allowed in the `StakeAndBake` contract
 * takes a variable size byte array so that we can independently specify the decoding
 * and contract call.
 * @author Lombard.Finance
 * @notice This contract is part of the Lombard.Finance protocol
 */
interface IDepositor {
    /**
     * @notice Deposit function interface.
     * @param owner The address of the user who will receive the shares
     * @param depositPayload Optional ABI encoded parameters needed for a vault deposit call
     * @return Number of shares minted for deposit
     */
    function deposit(
        address owner,
        uint256 depositAmount,
        bytes calldata depositPayload
    ) external returns (bytes memory);
}
